custom_css:
/* ★私人志_林雾金影@夜行性鲨鱼
禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎），无言退群的请不要用我的美化……
带符号💜的地方是自定义文字区域
气泡默认380px，太大太小可自行调换
想换图链的搜索关键词url */

@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
    /* font-feature-settings: "hwid"; 启用等宽变化字形 */
}


/* ★1. 气泡核心结构与封面设计 */
body.bubblechat .mes,body.bubblechat .mes[is_user="true"],.mes{padding:20px!important;padding-top:240px!important;padding-bottom:40px!important;border-radius:0!important;border:1px solid #DDE6D2!important;box-shadow:6px 6px 0 rgba(44,42,48,.04)!important;max-width:350px!important;margin:40px auto 25px auto!important;position:relative;background-color:#F3F6ED!important;background-image:none!important;box-sizing:border-box!important;overflow:visible!important}
.mes_block{width:100%!important;max-width:100%!important;padding:0!important;margin:0!important}
.mes_text{padding:0!important;margin:0!important;text-align:justify!important;text-justify:inter-ideograph!important;line-height:1.8!important}
.mes::before{content:''!important;position:absolute!important;top:15px!important;left:15px!important;right:15px!important;height:140px!important;background-image:url('https://iili.io/BS5wWaR.png')!important;background-size:cover!important;background-position:center 30%!important;filter:contrast(1.1) brightness(.9) sepia(.1) hue-rotate(-10deg)!important;z-index:1;border:1px solid #DDE6D2}
.mesAvatarWrapper{position:absolute!important;top:70px!important;left:25px!important;width:90px!important;height:115px!important;z-index:10!important;background:#F3F6ED!important;padding:5px!important;padding-bottom:30px!important;border:1px solid rgba(211, 210, 184, 1)!important;box-shadow:2px 4px 8px rgba(0,0,0,.08)!important;overflow:hidden!important;display:block!important}
.mesAvatarWrapper .avatar{width:80px!important;height:80px!important;position:relative!important;overflow:hidden!important;display:block!important;margin:0 auto!important}
.mesAvatarWrapper .avatar img{object-fit:cover!important;width:100%!important;height:100%!important;filter:grayscale(.2) contrast(1.05)!important}
.mesAvatarWrapper::before{content:"PRIVATE MANUSCRIPT"!important;/* 💜一般来说，没有改的必要 */position:absolute!important;left:4px!important;top:40px!important;transform:rotate(-90deg) translateY(-50%)!important;transform-origin:left center!important;font-size:7px!important;color:rgba(177, 172, 144, 1)!important;letter-spacing:1px!important;white-space:nowrap!important;z-index:10}
.mesAvatarWrapper::after{content:"禅"!important;/* 💜 */position:absolute!important;right:2px!important;bottom:2px!important;width:18px!important;height:18px!important;color:#B69933!important;font-size:10px!important;line-height:16px!important;text-align:center!important;font-weight:900!important;z-index:10!important;background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><filter id="r"><feTurbulence type="fractalNoise" baseFrequency="0.15" numOctaves="3"/><feDisplacementMap in="SourceGraphic" scale="8"/></filter><rect x="5" y="5" width="90" height="90" fill="none" stroke="%238A7A2F" stroke-width="10" filter="url(%23r)"/></svg>')!important;background-size:contain!important;background-repeat:no-repeat!important;filter:opacity(.85)!important}
.mes .name_text{position:absolute!important;left:130px!important;top:165px!important;font-size:1.4em!important;font-weight:700!important;color:rgba(48, 45, 32, 1)!important;letter-spacing:2px!important;z-index:10;background:#F3F6ED!important;padding:2px 8px!important;border:1px solid rgba(206, 200, 155, 1)!important;text-shadow:none!important}
.mes .name_text::after{content:"The flying bird leaps over."!important;/* 💜 */display:block!important;position:absolute;left:0;top:-18px;font-size:8px!important;letter-spacing:1px!important;color:#F3F6ED!important;background:#A99648!important;padding:2px 4px!important;white-space:nowrap}
.mes .mesIDDisplay{position:absolute!important;bottom:10px!important;left:15px!important;background:0 0!important;color:#fff!important;text-shadow:0 0 2px #000,0 0 1px #000!important;font-size:7px!important;z-index:15!important}
.mes .tokenCounterDisplay{position:absolute!important;bottom:18px!important;left:15px!important;background:0 0!important;color:#fff!important;text-shadow:0 0 2px #000,0 0 1px #000!important;font-size:7px!important;z-index:15!important}
.mes .mes_timer{position:absolute!important;bottom:26px!important;left:15px!important;background:0 0!important;color:#fff!important;text-shadow:0 0 2px #000,0 0 1px #000!important;font-size:7px!important;z-index:15!important}
.mes .timestamp{position:absolute!important;right:25px!important;top:130px!important;background:#F3F6ED!important;color:rgba(148, 139, 52, 1)!important;font-size:9px!important;padding:2px 6px!important;border:1px solid rgba(159, 152, 90, 1)!important;z-index:10!important;font-style:normal;border-top:1px solid rgba(196, 184, 122, 1);width:auto}

/* ★2. UI 全局深度重构 */
*{border-radius:0!important}
.text_pole,textarea,select,.menu_button,.character_select,.group_select,input[type="text"],input[type="number"]{background-color:#F3F6ED!important;border:1px solid rgba(184, 183, 154, 1)!important;color:rgba(155, 151, 113, 1)!important;border-radius:0!important;box-shadow:2px 2px 0 rgba(44,42,48,.05)!important;transition:all .2s ease}
.text_pole:focus,textarea:focus,select:focus{border-color:rgba(204, 196, 154, 1)!important;box-shadow:2px 2px 0 rgba(88,79,102,.2)!important;outline:none!important}
.menu_button{background-color:#E8F0E1!important;font-weight:700}
.menu_button:hover{background-color:#DDE6D2!important;color:#1a1a1a!important}
.inline-drawer-toggle,.list-group-item,.drawer-content .list-group-item,#extensions_menu .inline-drawer-toggle{background:#F3F6ED!important;background-image:none!important;border:1px solid rgba(184, 183, 154, 1)!important;margin:6px 8px!important;box-shadow:2px 2px 0 rgba(88,79,102,.08)!important;color:rgba(223, 217, 165, 1)!important;font-weight:700!important;padding:10px 15px!important;transition:all .2s ease!important}
.inline-drawer-toggle:hover,.list-group-item:hover{background:#E8F0E1!important;border-color:rgba(204, 195, 145, 1)!important;transform:translate(-1px,-1px);box-shadow:3px 3px 0 rgba(88,79,102,.2)!important;color:#1a1a1a!important}
.inline-drawer-toggle i,.inline-drawer-toggle .fa-chevron-down,.inline-drawer-toggle .fa-chevron-right,.inline-drawer-icon{color:rgba(226, 222, 189, 1)!important;text-shadow:none!important}
#right-nav h4,#left-nav h4,.inline-drawer-header h4,.standoutHeader,.drawer-content h4{background:rgba(226, 221, 194, 1)!important;color:#F3F6ED!important;border:1px solid rgba(215, 216, 167, 1)!important;padding:8px 12px!important;margin:15px 8px 10px 8px!important;letter-spacing:2px!important;text-transform:uppercase;font-size:14px!important;box-shadow:3px 3px 0 rgba(240, 237, 222, 1)!important;text-align:center!important;text-shadow:none!important}
.mes_text h1,.mes_text h2,.mes_text h3,.mes_text h4{background:transparent!important;color:rgba(222, 218, 178, 1)!important;border:none!important;border-bottom:1px solid rgba(209, 211, 184, 1)!important;box-shadow:none!important;margin:15px 0 10px 0!important;padding:0 0 5px 0!important;text-align:left!important}
#completion_prompt_manager_list{background-color:transparent!important;border:none!important}#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,#completion_prompt_manager_list .completion_prompt_manager_prompt_name *,#completion_prompt_manager_list .text_muted,.completion_prompt_manager_prompt_name{color:rgba(207, 208, 163, 1)!important;opacity:1!important;-webkit-text-fill-color:rgba(235, 232, 205, 1)!important;text-shadow:none!important}
input[type="range"]{-webkit-appearance:none!important;appearance:none!important;background:rgba(233, 232, 202, 1)!important;height:3px!important;border:none!important;box-shadow:none!important;outline:none!important;filter:none!important;mix-blend-mode:normal!important;opacity:1!important;overflow:visible!important}
input[type="range"]::-webkit-slider-thumb,input[type="range"]::-moz-range-thumb{-webkit-appearance:none!important;width:34px!important;height:24px!important;background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETC_xp3dchOl0puQOzypdZn0dWaU9lRAACVzAAAhLf8FZurhUfAVmdHDsE.png')center/contain no-repeat!important;border:0!important;border-radius:0!important;filter:drop-shadow(1px 1px 0 rgba(44,42,48,.2)) grayscale(.8)!important}
input[type="checkbox"]{border-radius:0!important;-webkit-appearance:none;appearance:none;background:0 0!important;border:1px solid rgba(239, 237, 185, 1)!important;width:16px;height:16px;position:relative;vertical-align:middle;cursor:pointer;outline:none!important}input[type="checkbox"]:checked{border-color:rgba(197, 194, 145, 1)!important;background:0 0!important}input[type="checkbox"]::before{content:none!important}input[type="checkbox"]:checked::after{content:''!important;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)!important;width:14px;height:14px;background:url('https://iili.io/BS5Xnhg.png')center/cover no-repeat!important;filter:contrast(1.2)!important}
::-webkit-scrollbar{display:none}
#top-bar{margin:0 auto;left:0;right:0;display:inline-block;height:24px;position:absolute;box-shadow:none;opacity:0;z-index:3005}.drawer-icon{transform:scale(.55);color:rgba(209, 204, 158, 1)}
#send_form{display:flex;flex-wrap:wrap;align-items:center;width:94%!important;max-width:800px;margin:10px auto!important;background:#F3F6ED!important;border:1px solid rgba(181, 171, 118, 1)!important;border-radius:0!important;box-shadow:4px 4px 0 rgba(44,42,48,.04)!important}
#nonQRFormItems{padding:4px 12px!important;position:relative;display:flex;flex-direction:row;column-gap:5px;order:25;width:100%;min-height:40px!important;align-items:center;overflow:hidden;background-color:#F3F6ED!important;border:none!important;box-shadow:none!important;z-index:50}
.qr--buttons{opacity:0;visibility:hidden;max-height:0;margin:0!important;padding:0!important;transform:translateY(15px);transition:all .3s cubic-bezier(.2,1,.3,1);overflow:hidden}
#send_form:focus-within .qr--buttons{opacity:1;visibility:visible;max-height:300px;margin-bottom:8px!important;transform:translateY(0);pointer-events:auto}
#rightSendForm>div:not(.mes_stop),#leftSendForm>div{transform:scale(.6)!important;color:rgba(223, 220, 190, 1)}
#send_textarea{background:0 0!important;border:0!important;box-shadow:none!important;color:rgba(228, 222, 191, 1)!important}#send_textarea::placeholder,#send_textarea::-webkit-input-placeholder{color:transparent!important;opacity:0!important;-webkit-text-fill-color:transparent!important}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before{content:"万古长空，一朝风月。"!important;/* 💜 */position:absolute!important;top:50%!important;left:55%!important;transform:translate(-50%,-50%)!important;font-style:normal!important;font-size:10px!important;pointer-events:none!important;z-index:10!important;white-space:nowrap!important;color:rgba(231, 217, 190, 1)!important;letter-spacing:1px}
#chat{-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 15px,#000 calc(100% - 25px),transparent 100%);mask-image:linear-gradient(to bottom,transparent 0,#000 15px,#000 calc(100% - 25px),transparent 100%)}
.mes_reasoning_details{width:100%!important;margin:15px 0!important;border:0!important;background:0 0!important;overflow:visible!important}
.mes_reasoning_header,.mes_reasoning_summary,.mes_reasoning_header_text{background:#E8F0E1!important;background-image:none!important;box-shadow:none!important;border-radius:0!important}
.mes_reasoning_summary{width:100%!important;box-sizing:border-box!important;border:1px solid rgba(209, 211, 184, 1)!important;border-left:4px solid rgba(218, 214, 179, 1)!important;padding:8px 15px!important;color:rgba(178, 174, 153, 1)!important;position:relative!important;display:flex!important;align-items:center!important;min-height:32px!important;cursor:pointer!important;box-shadow:3px 3px 0 rgba(88,79,102,.1)!important;justify-content:flex-start!important}
.mes_reasoning_summary::after{content:''!important;position:absolute;left:8px;top:50%;transform:translateY(-50%)!important;width:18px;height:12px;background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETC_xp3dchOl0puQOzypdZn0dWaU9lRAACVzAAAhLf8FZurhUfAVmdHDsE.png')center/contain no-repeat!important;filter:drop-shadow(1px 1px 0 #fff) grayscale(1)!important}
.mes_reasoning{width:100%!important;box-sizing:border-box!important;background:#F9F8FA!important;border:1px dashed rgba(184, 183, 154, 1)!important;border-top:0!important;color:rgba(208, 207, 183, 1)!important;font-size:.9em!important;line-height:1.7!important;padding:15px!important;margin:0!important}
.mes_reasoning_header_icon,.mes_reasoning_details summary::marker{position:absolute!important;right:10px!important;top:50%;transform:translateY(-50%)!important;color:rgba(207, 195, 154, 1)!important}

/* ★3. Markdown 文本美学重构 */
.mes_text strong{color:rgba(216, 215, 173, 1)!important;font-weight:900!important;background:none!important;text-shadow:1px 1px 0 rgba(255,255,255,.6),-1px -1px 0 rgba(88,79,102,.1)!important}
.mes_text em{position:relative!important;padding-left:18px!important;font-style:italic!important;color:rgba(227, 223, 186, 1)!important;display:inline-block!important}
.mes_text em::before{content:''!important;position:absolute!important;left:0;top:50%;transform:translateY(-50%)!important;width:16px;height:10px;background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETC_xp3dchOl0puQOzypdZn0dWaU9lRAACVzAAAhLf8FZurhUfAVmdHDsE.png')center/contain no-repeat!important}
q{background:rgba(88,79,102,.08)!important;color:rgba(202, 190, 133, 1)!important;border-left:2px solid rgba(217, 212, 186, 0.94)!important;padding:0 8px!important;font-style:italic!important;margin:0 4px!important;display:inline-block!important}
:not(pre)>code{background:rgba(219, 214, 168, 1)!important;color:#F3F6ED!important;padding:2px 6px!important;border:none!important;margin:0 2px!important;font-weight:700!important;border-left:2px solid rgba(218, 213, 183, 1)!important;box-shadow:1px 1px 0 rgba(0,0,0,.15)!important}
blockquote{margin:25px 0!important;padding:25px 15px 15px 15px!important;background:#F9F8FA!important;border:1px solid #DDE6D2!important;position:relative!important;display:block!important;box-shadow:none!important;color:rgba(206, 203, 180, 1)!important;font-style:normal!important}
blockquote::before{content:'行者常至'!important;/* 💜 */position:absolute;top:-8px;left:15px;background:rgba(187, 189, 155, 1);color:#F3F6ED;font-size:8px;padding:2px 8px;letter-spacing:1px;font-weight:700!important}
pre{background:rgba(222, 217, 195, 1)!important;color:#C0AD5F!important;border:1px solid rgba(220, 215, 188, 1)!important;box-shadow:4px 4px 0 rgba(88,79,102,.15)!important;margin:20px 0!important;padding:28px 12px 12px!important;position:relative!important}
pre code,pre span{background:0 0!important;color:inherit!important;text-shadow:none!important}
pre::before{content:'高山仰止，景行行止。'!important;/* 💜 */position:absolute;top:0;left:0;font-size:8px!important;font-weight:700!important;color:#E2D079!important;background:transparent!important;padding:4px 10px 4px 28px!important;letter-spacing:1px}
pre::after{content:''!important;position:absolute;top:3px;left:8px;width:16px;height:12px;background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETC_xp3dchOl0puQOzypdZn0dWaU9lRAACVzAAAhLf8FZurhUfAVmdHDsE.png')center/contain no-repeat!important;filter:grayscale(1) opacity(.8) drop-shadow(1px 1px 0 #000)!important;z-index:10}

/* ★4. 弹窗 (Toast) 美化 */
#toast-container>.toast{color:rgba(215, 216, 188, 1)!important;background:#F3F6ED!important;border:1px solid rgba(206, 206, 173, 1)!important;outline:none!important;box-shadow:6px 6px 0 rgba(88, 79, 102, 0.15)!important;padding:15px 15px 15px 45px!important;border-radius:0!important;position:relative!important;overflow:visible!important}
#toast-container>.toast::after{content:"风动了。";/* 💜 */position:absolute;right:8px;bottom:4px;font-size:7px;color:rgba(237, 213, 150, 1);letter-spacing:1px}
#toast-container>.toast::before{content:''!important;position:absolute!important;left:18px!important;top:50%!important;transform:translateY(-50%)!important;width:16px!important;height:16px!important;background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETC_xp3dchOl0puQOzypdZn0dWaU9lRAACVzAAAhLf8FZurhUfAVmdHDsE.png')center/contain no-repeat!important}
#toast-container>.toast-success::before{filter:grayscale(1) opacity(.7)!important}
#toast-container>.toast-error::before{background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETDY5p3dzrHJzABytWPPppRE9WDKO6cAAC6zEAAhLf8Fa2C-1QMNU61zsE.jpg')center/contain no-repeat!important;width:16px!important;height:16px!important;left:14px!important;top:50%!important;filter:grayscale(1) contrast(1.2)!important}
#toast-container>.toast-info::before{filter:grayscale(.8) hue-rotate(250deg) brightness(.8)!important}
#toast-container>.toast-warning::before{background:url('https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAETDY5p3dzrHJzABytWPPppRE9WDKO6cAAC6zEAAhLf8Fa2C-1QMNU61zsE.jpg')center/contain no-repeat!important;width:16px!important;height:16px!important;left:14px!important;top:50%!important;filter:grayscale(1) opacity(.8)!important}
